from tools19 import *
screens={
'Plane183':('Screened out: coloring successive plate sides supplies no selective wrong correspondence; extra radial lines could be read as additional plate seams.','Each ring corner leaves 360-2*108=144 degrees after the two regular-pentagon angles. The regular inner ring has interior angle 180-360/n=144, hence n=10.'),
'Plane229':('Screened out: the useful distinction is corner versus side counting; adding contours through gray cells could change the apparent frame partition, while coloring an arbitrary count of cells is not a substantive correspondence.','A one-unit-wide frame around n by n contains (n+2)^2-n^2=4n+4 squares. At n=7 this is 32; n=10 gives 44.'),
'Plane269':('Screened out: exact tooth counts are textual and telescope. Recoloring cog rims or hubs does not provide a useful wrong feature-to-feature relation; no changed teeth or contact geometry allowed.','Each mesh preserves teeth passed. Last turns/first turns=30/10=3; the two intermediate counts cancel. Three external meshes reverse direction but not the turn magnitude.'),
'Plane284':('Screened out: colored asymmetric portions or dashed symmetry candidates may themselves change the axes-of-symmetry target. Whole-option styling would be mere salience.','C has horizontal and vertical reflection axes. A arrow and E car have at most one; D bent arrow has fewer than two, and the slashed turn sign B also has fewer than two. Thus C uniquely maximizes the count.'),
'Plane286':('Tested purposeful exposed-side correspondence.','See immutable design.json and primary_review.json for A impossibility and constructions of B-E.'),
'Plane295':('Tested purposeful inner-ear shoulder correspondence; explicit appearance-versus-printed-detail semantic risk queued for independent review.','See immutable design.json for exact ear and nose comparisons; B preserves the original features.'),
'Plane299':('Hypothesis rejected before image/API: desired actual quarter-arc objects o18/o38/o100/o102 have authoritative styleable=false because they are no-outline semantic-fill patches. No bypass using changed fill or fabricated outline. Fresh context and preparation error retained.','Gap corners require spike, small quarter, spike, large quarter in clockwise order from TL. Only E has that feature multiset, and a 90-degree clockwise turn fits. Others have different spike/small/large counts. See make19.py frozen hypothesis text.'),
'Plane329':('Screened out: any selective animal-curve color/width correspondence could alter the very symmetry count being asked. Auxiliary apparent axes introduce lines into the counted figure.','Vertical and horizontal reflections preserve the four animal outlines and square boundary; diagonal reflections do not preserve the head/ear profiles. Exactly 2.'),
'Plane330':('Screened out: no input-to-wrong-answer correspondence without presenting selected bars as a proposed move sequence or joining independent bars into a misleading region. No forced two-bar highlight.','Minimum 3 distinct moved bars. Exhaustive zero/one/two movable-subset BFS and a three-bar witness saved in ../sliding_bar_proof.json.'),
'Plane341':('Screened out: altering the traffic sign appearance can change its symmetry; red/blue/yellow fills are semantic and preserved. Additional candidate axes risk adding counted ink.','A no-stopping X sign has 4 axes. C equilateral triangle has 3; B striped diamond at most 2, D circular arrows have chiral rotation without reflection, E dead-end has 1. A uniquely maximizes.'),
'Plane342':('Tested purposeful wedge-edge orientation correspondence; printed-card color interpretation is explicitly a second-review concern.','Composition of downward and right flips is (x,y)->(-x,-y). Left wedge becomes right, preserving the NW-SE diagonal direction. Only B.'),
'Plane353':('Screened out: digits are the operative information and cannot be edited. Coloring individual digit boxes would chiefly choose an answer row; no justified geometric misbinding beyond arbitrary row salience.','Ten equally spaced positions put the opposite code 5 positions away. Center digits 6348 become 1893 modulo 10, choice B. The adjacent rows shift by the same +5.'),
'Plane358':('Screened out: hole separation is directly visible and numerals are immutable. A false connecting chord to unrelated dial positions would add an unsupported correspondence rather than clarify a real input feature.','Holes initially show 1 and 5, separated by 4 hour steps. If either shows 8, other is 8+/-4 modulo 12, namely 12 or 4, choice A.'),
'Plane361':('Tested one purposeful diagonal-to-terminal-arc radius hypothesis.','Three quarter-turns have P radii 10,10sqrt(2),10, giving 10pi+5pi sqrt(2), choice C. Full proof and marker roles in immutable design.'),
'Plane372':('Screened out after checking locus geometry: each option repeats its own road, and coloring just a wrong rounded valley would mainly select a locus. There is no corresponding original rounded feature at a sharp road valley to bind without inventing new path ink. Native fragmentation is not itself the reason to reject.','On straight slopes the center follows parallel offsets. At convex peaks it traces radius-r arcs; at concave valleys the offset segments meet in a sharp V where support switches. Only E combines rounded peaks and sharp valleys.'),
'Plane377':('Tested purposeful same-handed hypotenuse correspondence.','Exactly 3 reflected pairs. Top arrows, upper triangles and downward arrows coincide. Circle positions differ; bottom triangles have the same handedness and therefore fail reflection. Exact coordinates in design.'),
'Plane379':('Screened out for the same concrete reason as Plane358, assessed separately with its different target number. No redundant calls on near-identical hole geometry.','Initial holes 1 and 5 are 4 hours apart. With 10 exposed, the other is 10+/-4 modulo 12, namely 2 or 6, choice A.'),
'Plane383':('Screened out: recoloring grid segments as if walls would alter the semantic bold-wall distinction; adding a wrong route would present an unsupported selected answer. Existing wall styling that preserves meaning supplies no useful wrong correspondence.','From eastward entry in row 2, path reaches Q2, turns via Q1,P1,P4,T4,T1,S1,S4,T4. The oriented state at T4 repeats and gives an endless loop. Correct E.'),
'Plane386':('Screened out after solving its own current bars: the same structural obstacle as Plane330; no legal distinct useful feature binding beyond selected-bar salience or misleading unions.','Same seven 1x3 bars in a 5x5 box. The exhaustive movable-subset proof gives minimum 3; see ../sliding_bar_proof.json.'),
'Plane389':('Screened out: extra region outlines could look like another ship and change the count target. Styling forbidden boundary contacts is truthful guidance; a wrong-cell grouping would be arbitrary count salience.','Chebyshev-neighbor exclusion of existing cells (0,3),(1,0),(1,1), with x left/y bottom zero-based, leaves two horizontal placements in rows 3,4 plus three vertical placements each in columns 3,4. Total 8. All placements saved in primary_enumeration.json.')}
audits=[];global_names={'PlaneGeometry/dataset.jsonl','provenance/approvals.json','provenance/source_notes.json'}
for qid in ASSIGNED:
    out=HERE/qid;start=read(out/'input_fingerprints.json');e=eligibility(qid)
    changed=[];global_changes=[];missing=[]
    for rel,old in start['files'].items():
        p=ROOT/rel;current=file_hash(p) if p.exists() else None
        if current!=old:
            (global_changes if rel.replace('\\','/') in global_names else changed).append({'path':rel,'before':old,'after':current})
        if not p.exists():missing.append(rel)
    record=e['formal_record'];record_equal=canonical_hash(record)==start['question_record_sha256']
    for dest,key in [('source_original.jpg','original_image'),('source_scene_snapshot.json','scene')]:
        p=ROOT/'PlaneGeometry'/record[key]
        if p.exists() and not (out/dest).exists():(out/dest).write_bytes(p.read_bytes())
    audit={'question_id':qid,'checked_at':now(),'eligible_current':e['eligible'],'eligibility':e,'formal_record_hash_unchanged':record_equal,'individual_frozen_input_changes':changed,'missing_inputs':missing,'aggregate_state_file_changes':global_changes,'aggregate_classification':'Diagnostic only if unrelated records changed; individual formal record, approval fingerprint, inputs and eligibility remain decisive. No files restored.','current_approval_fingerprint_matches_start':e['approval_current_fingerprint']==read(out/'eligibility_start.json')['approval_current_fingerprint'],'native_no_op_pixel_equality_verified_at_inspection':True,'formal_png_native_size_viewed':True,'source_jpg_exists':(out/'source_original.jpg').exists(),'source_jpg_actually_viewed':qid in ['Plane286','Plane295','Plane299','Plane342','Plane361','Plane377']}
    assert record_equal and not changed and not missing and e['eligible']
    write(out/'source_audit_final.json',audit)
    if not (out/'assessment.json').exists():write(out/'assessment.json',{'question_id':qid,'assessed_at':now(),'assessment':screens[qid][0],'primary_math':screens[qid][1],'formal_png_actually_viewed':True,'baseline_pixel_equal_formal':True,'source_audit':'source_audit_final.json','approval_status':'No Pass, Collect, formal review or publication'})
    audits.append(audit)
allocations={}
for p in BASE.glob('background_*_assignment.json'):
    for q in read(p).get('question_ids',[]):
        if q in ASSIGNED:allocations.setdefault(q,[]).append(p.name)
assert all(v==['background_19_assignment.json'] for v in allocations.values()) and set(allocations)==set(ASSIGNED)
write(HERE/'source_and_allocation_audit.json',{'checked_at':now(),'assigned_count':len(ASSIGNED),'question_ids':ASSIGNED,'allocation_membership':allocations,'all_frozen_question_inputs_unchanged':True,'current_eligibility_all_true':True,'audits':audits,'workspace_claim':'Only assigned frozen inputs checked; no claim that concurrently edited whole workspace is unchanged.','own_write_guard':'tools19 installs shared runtime_isolation before project renderer imports and adds a stricter guard restricting all subsequent Python writes to background_19. Harness copied byte-identically under own root and only PROJECT/RUNTIME context globals rebound.','shared_helpers_modified':False,'formal_library_or_approvals_written':False})
write(HERE/'protocol_read_log.json',{'read_in_full':['runtime/mathvision_special_20261101/background_19_brief.txt','runtime/mathvision_special_20261101/background_19_assignment.json','runtime/mathvision_special_20261101/continuation_brief.txt','runtime/mathvision_special_20261101/parallel_expansion_20261101.json','AGENTS.md','MATHPALETTE_PROTOCOL.md','PlaneGeometry/REDRAW_PROTOCOL.md','PlaneGeometry/dataset_generator/protocol.json','PlaneGeometry/workbench/README.md','PlaneGeometry/workbench/agent_prompt.md','PlaneGeometry/workbench/plugin.schema.json'],'user_overrides':'Own runtime folder, autonomous purposeful designs and exactly-two calls permitted; formal review/Pass/Collect still forbidden. No nested agents.','inventory_and_previous_attempts':'Inventory read; remaining rows and exploration attempts reviewed per question in eligibility_start.json. All assigned questions fresh at start.'})
